<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activate account</title><link rel="stylesheet" href="<?= e(asset('vendor/bootstrap/bootstrap.min.css')) ?>"><script defer src="<?= e(asset('js/security/activation.js')) ?>"></script></head><body class="bg-body-tertiary"><main class="container py-5" style="max-width:600px"><section class="card card-body p-4"><h1 class="h3">Activate your account</h1><p>Choose a unique password. Activation does not start a scheduled appointment early.</p><?php foreach($_SESSION['flashes']??[] as $notice): ?><p class="alert alert-info"><?= e($notice['message']) ?></p><?php endforeach; unset($_SESSION['flashes']); ?><form method="post" action="<?= e(url()) ?>"><?= csrf() ?><input type="hidden" name="_action" value="activate_account"><?= input('activation_token','Activation code','','text',true,'maxlength="64" autocomplete="off" data-activation-token') ?><?= input('password','New password','','password',true,'minlength="12" maxlength="128" autocomplete="new-password"') ?><?= input('password_confirmation','Confirm password','','password',true,'minlength="12" maxlength="128" autocomplete="new-password"') ?><button class="btn btn-primary">Activate account</button> <a class="btn btn-light" href="<?= e(url('login')) ?>">Sign in</a></form></section></main></body></html>
